mapper.select:
SELECT

FROM NOTICE
WHERE NOTICE_STATUS = 'Y'
  AND (
    NOTICE_MODIFIEDDATE > #{noticeModifiedDate}
    OR (
      NOTICE_MODIFIEDDATE = #{noticeModifiedDate}
      AND NOTICE_NO > #{noticeNo}
    )
  )
ORDER BY NOTICE_MODIFIEDDATE ASC, NOTICE_NO ASC
LIMIT 1

SELECT

FROM NOTICE
WHERE NOTICE_STATUS = 'Y'
  AND (
    NOTICE_MODIFIEDDATE < #{noticeModifiedDate}
    OR (
      NOTICE_MODIFIEDDATE = #{noticeModifiedDate}
      AND NOTICE_NO < #{noticeNo}
    )
  )
ORDER BY NOTICE_MODIFIEDDATE DESC, NOTICE_NO DESC
LIMIT 1
